#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007LL;

struct Mat2 {
    long long a[2][2];
    Mat2() { a[0][0]=a[0][1]=a[1][0]=a[1][1]=0; }
    Mat2(long long _00, long long _01, long long _10, long long _11) {
        a[0][0]=_00; a[0][1]=_01; a[1][0]=_10; a[1][1]=_11;
    }
};

Mat2 mul(const Mat2 &x, const Mat2 &y) {
    Mat2 r;
    r.a[0][0] = (x.a[0][0]*y.a[0][0] + x.a[0][1]*y.a[1][0]) % MOD;
    r.a[0][1] = (x.a[0][0]*y.a[0][1] + x.a[0][1]*y.a[1][1]) % MOD;
    r.a[1][0] = (x.a[1][0]*y.a[0][0] + x.a[1][1]*y.a[1][0]) % MOD;
    r.a[1][1] = (x.a[1][0]*y.a[0][1] + x.a[1][1]*y.a[1][1]) % MOD;
    return r;
}

Mat2 mpow(Mat2 base, long long exp) {
    Mat2 res(1,0,0,1);
    while (exp > 0) {
        if (exp & 1) res = mul(res, base);
        base = mul(base, base);
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long p;
    if(!(cin >> n >> p)) return 0;

    if (p <= 2) {
        cout << 0 << "\n";
        return 0;
    }

    vector<long long> s_vec;
    long long curr = p - 1;
    while (curr > 0) {
        s_vec.push_back(curr);
        curr >>= 1;
    }
    s_vec.push_back(0);
    sort(s_vec.begin(), s_vec.end());
    s_vec.erase(unique(s_vec.begin(), s_vec.end()), s_vec.end());

    auto get_S = [&](long long x) -> long long {
        if (x < 0) return 0;
        if (x == 0) return 0;
        if (x == 1) return 1 % MOD;
        if (x == 2) return 2 % MOD;
        Mat2 base(3, MOD-1, 1, 0);
        Mat2 m = mpow(base, x - 2);
        long long S_x = (m.a[0][0] * 2 + m.a[0][1] * 1) % MOD;
        return S_x;
    };

    unordered_map<long long, long long> S_map;
    for (long long s : s_vec) {
        S_map[s] = get_S(s);
    }

    vector<long long> count_g(3, 0);
    for (long long len = 1; len <= p - 1; ) {
        long long g;
        if (len == 1 || len == 2) g = 0;
        else if (len == 3 || len == 4) g = 1;
        else g = 2;

        long long max_len;
        if (g == 0) max_len = 2;
        else if (g == 1) max_len = 4;
        else max_len = p - 1;

        long long R = min(max_len, p - 1);
        long long cnt = R - len + 1;
        count_g[g] = (count_g[g] + cnt) % MOD;
        len = R + 1;
    }

    long long A = (count_g[1] + count_g[2]) % MOD;
    long long B = count_g[0] % MOD;

    vector<long long> dp(n + 1, 0), ndp(n + 1, 0);
    dp[0] = 1;
    for (int i = 0; i < n; ++i) {
        fill(ndp.begin(), ndp.end(), 0);
        for (int j = 0; j <= n; ++j) {
            if (dp[j] == 0) continue;
            ndp[j] = (ndp[j] + dp[j] * B) % MOD;
            if (j + 1 <= n) ndp[j + 1] = (ndp[j + 1] + dp[j] * A) % MOD;
        }
        dp.swap(ndp);
    }

    long long ans = 0;
    for (int j = 1; j <= n; j += 2) {
        ans = (ans + dp[j]) % MOD;
    }
    cout << ans << "\n";
    return 0;
}
